// Generated by tooling/unicode-cases/normalization.ts; Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, Staying identical to node.
// Each FNV-1a digest consumes normalized UTF-16 code units in code-point order.
// The BMP plane includes every lone surrogate U+D800-U+DFFF.
const expected = [3782273815, 1377090590, 2723754780, 1090022853, 3680693701, 2194763205, 2892066245, 1899982277, 362769861, 2643684805, 4271041989, 1260613061, 3317034437, 3690163653, 1459252677, 2971056427];
const blocks = ["NFC U+000000-U+000FFF", "NFC U+001000-U+001FFF", "NFC U+002000-U+002FFF", "NFC U+003000-U+003FFF", "NFC U+004000-U+004FFF", "NFC U+005000-U+005FFF", "NFC U+006000-U+006FFF", "NFC U+007000-U+007FFF", "NFC U+008000-U+008FFF", "NFC U+009000-U+009FFF", "NFC U+00A000-U+00AFFF", "NFC U+00B000-U+00BFFF", "NFC U+00C000-U+00CFFF", "NFC U+00D000-U+00DFFF", "NFC U+00E000-U+00EFFF", "NFC U+00F000-U+00FFFF"];
for (let block = 0; block < expected.length; block++) {
  let hash = 2166136261;
  const start = 0 + block * 4096;
  for (let point = start; point < start + 4096; point++) {
    const output = String.fromCodePoint(point).normalize("NFC");
    for (let unit = 0; unit < output.length; unit++) {
      hash = Math.imul(hash ^ output.charCodeAt(unit), 16777619) >>> 0;
    }
  }
  assert.sameValue(hash, expected[block], blocks[block]);
}
